from itertools import permutations

def count_distinct_strings(grid):
    n = len(grid[0])
    # Create a graph where each cell is a node and edges represent possible moves
    graph = {i: [] for i in range(n)}
    for i in range(n):
        if i > 0:
            graph[i].append(i - 1)
        if i < n - 1:
            graph[i].append(i + 1)
        graph[i].append((i - 1 + n) % n)
        graph[i].append((i + 1) % n)

    # Generate all possible paths using DFS
    def dfs(path, visited):
        if len(path) == n:
            return 1
        count = 0
        for neighbor in graph[path[-1]]:
            if neighbor not in visited:
                visited.add(neighbor)
                count += dfs(path + [neighbor], visited)
                visited.remove(neighbor)
        return count

    total_count = 0
    for start in range(n):
        visited = set([start])
        total_count += dfs([start], visited)

    return total_count

